// Stand-in for the board-level lint (make lint in top/<design>/): only the
// ports, so that the instance connecting to it elaborates. The Xilinx
// primitives come from Yosys's cell library (top_rules.mk).

// The EVR GT, generated by Vivado at build time (GT_TCL); ports as
// evr_gt_wrapper.v connects them. Verilator resolves the pins of the GTY branch
// too, which Marble (GTX) does not build, so the stub has both sets.
module evr_gt (
    input        sysclk_in,
    input        soft_reset_rx_in,
    input        dont_reset_on_data_error_in,
    output       gt0_tx_fsm_reset_done_out,
    output       gt0_rx_fsm_reset_done_out,
    input        gt0_data_valid_in,
    output       gt0_cpllfbclklost_out,
    output       gt0_cplllock_out,
    input        gt0_cplllockdetclk_in,
    input        gt0_cpllreset_in,
    input        gt0_gtrefclk0_in,
    input        gt0_gtrefclk1_in,
    input  [8:0] gt0_drpaddr_in,
    input        gt0_drpclk_in,
    input [15:0] gt0_drpdi_in,
    input        gt0_drpen_in,
    input        gt0_drpwe_in,
    output [7:0] gt0_dmonitorout_out,
    input        gt0_eyescanreset_in,
    input        gt0_rxuserrdy_in,
    output       gt0_eyescandataerror_out,
    input        gt0_eyescantrigger_in,
    output [15:0] gt0_rxdata_out,
    input        gt0_rxusrclk_in,
    input        gt0_rxusrclk2_in,
    output [1:0] gt0_rxcharisk_out,
    output [1:0] gt0_rxdisperr_out,
    output [1:0] gt0_rxnotintable_out,
    input        gt0_gtxrxp_in,
    input        gt0_gtxrxn_in,
    output [4:0] gt0_rxphmonitor_out,
    output [4:0] gt0_rxphslipmonitor_out,
    input        gt0_rxdfelpmreset_in,
    output [6:0] gt0_rxmonitorout_out,
    input  [1:0] gt0_rxmonitorsel_in,
    output       gt0_rxoutclk_out,
    output       gt0_rxoutclkfabric_out,
    input        gt0_gtrxreset_in,
    input        gt0_rxpmareset_in,
    input        gt0_rxslide_in,
    output       gt0_rxresetdone_out,
    input        gt0_gttxreset_in,
    input        gt0_qplloutclk_in,
    input        gt0_qplloutrefclk_in,
    // GTY (gtwizard_ultrascale)
    input        gtwiz_userclk_tx_reset_in,
    output       gtwiz_userclk_tx_srcclk_out,
    output       gtwiz_userclk_tx_usrclk_out,
    output       gtwiz_userclk_tx_usrclk2_out,
    output       gtwiz_userclk_tx_active_out,
    input        gtwiz_userclk_rx_reset_in,
    output       gtwiz_userclk_rx_srcclk_out,
    output       gtwiz_userclk_rx_usrclk_out,
    output       gtwiz_userclk_rx_usrclk2_out,
    output       gtwiz_userclk_rx_active_out,
    input        gtwiz_buffbypass_rx_reset_in,
    input        gtwiz_buffbypass_rx_start_user_in,
    output       gtwiz_buffbypass_rx_done_out,
    output       gtwiz_buffbypass_rx_error_out,
    input        gtwiz_reset_clk_freerun_in,
    input        gtwiz_reset_all_in,
    input        gtwiz_reset_tx_pll_and_datapath_in,
    input        gtwiz_reset_tx_datapath_in,
    input        gtwiz_reset_rx_pll_and_datapath_in,
    input        gtwiz_reset_rx_datapath_in,
    output       gtwiz_reset_rx_cdr_stable_out,
    output       gtwiz_reset_tx_done_out,
    output       gtwiz_reset_rx_done_out,
    input [15:0] gtwiz_userdata_tx_in,
    output [15:0] gtwiz_userdata_rx_out,
    input        drpclk_in,
    input        gtrefclk0_in,
    input        gtyrxn_in,
    input        gtyrxp_in,
    input        rx8b10ben_in,
    input        tx8b10ben_in,
    input [15:0] txctrl0_in,
    input [15:0] txctrl1_in,
    input  [7:0] txctrl2_in,
    output       cplllock_out,
    output       gtpowergood_out,
    output       gtytxn_out,
    output       gtytxp_out,
    output [15:0] rxctrl0_out,
    output [15:0] rxctrl1_out,
    output [7:0] rxctrl2_out,
    output [7:0] rxctrl3_out,
    output       rxpmaresetdone_out,
    output       txpmaresetdone_out
);
endmodule
